from pathlib import Path
import pandas as pd


# Project reports directory
REPORTS_DIR = Path(__file__).resolve().parents[2] / "reports"

# Forecast output generated by the ML component
FORECAST_FILE = REPORTS_DIR / "final_dl_predictions.csv"

REQUIRED_COLUMNS = [
    "Datetime",
    "Actual",
    "Predicted",
    "Residual"
]


def get_forecast_data(limit: int = 100):
    """
    Load the latest forecast results produced by the forecasting component.
    """

    # Check whether the ML output exists
    if not FORECAST_FILE.exists():
        raise FileNotFoundError(
            f"Forecast output file not found: {FORECAST_FILE}"
        )

    # Load forecasting results
    df = pd.read_csv(FORECAST_FILE)

    # Validate required columns
    missing_columns = [
        column
        for column in REQUIRED_COLUMNS
        if column not in df.columns
    ]

    if missing_columns:
        raise ValueError(
            f"Forecast output is missing columns: {missing_columns}"
        )

    # Make sure there is data available
    if df.empty:
        return []

    # Convert datetime to a consistent format
    df["Datetime"] = pd.to_datetime(
        df["Datetime"],
        errors="coerce"
    )

    # Remove records with invalid timestamps
    df = df.dropna(subset=["Datetime"])

    # Return latest records
    df = df.tail(limit).copy()

    # JSON-safe datetime strings
    df["Datetime"] = df["Datetime"].dt.strftime(
        "%Y-%m-%dT%H:%M:%S"
    )

    # Replace NaN values because JSON should not contain NaN
    df = df.where(pd.notnull(df), None)

    return df[REQUIRED_COLUMNS].to_dict(orient="records")